(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*20+Math.cos(y*0.013-t*0.18)*15;
  const w1y = Math.cos(y*0.016-t*0.22)*20+Math.sin(x*0.014+t*0.3)*15;
  const w2x = Math.sin((x+w1x)*0.025-t*0.15)*12+Math.cos((y+w1y)*0.02+t*0.12)*8;
  const w2y = Math.cos((y+w1y)*0.022+t*0.17)*12+Math.sin((x+w1x)*0.019-t*0.14)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.7],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,1.3],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*40,0.05,2.8,0.6],
    [200+Math.sin(t*0.38)*110,220+Math.cos(t*0.48+2)*70,0.085,1.85,1.05],
    [300+Math.cos(t*0.42+1)*90,30+Math.sin(t*0.58+3)*55,0.075,2.35,0.95]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    hS+=Math.sin(d*f*1.4-t*sp*0.8+3)*amp*0.5;
  }
  const act=aS/10,inh=iS/10,harm=hS/10;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.065+sy*0.08-t*1.5)*0.15+Math.sin(sx*0.09-sy*0.07+t*1.8)*0.1;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)*0.25+Math.sin(dist*0.04+ang*4-t*1.2)*0.25+Math.sin(dist*0.08-t*2)*Math.cos(ang*2+t*0.5)*0.15);
  const cell=(Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.7)*Math.cos(sx*0.1+sy*0.06-t*0.5)*0.3)/1.3;
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+spiral+harm*0.3)*2);
  const blend=reaction*0.7+Math.tanh(cell*1.5)*0.3;
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.35-t*2.5)*0.04;
  const v=Math.max(0,Math.min(1,blend*0.5+0.5+micro));
  const pal=[[5,12,42],[12,48,72],[18,95,105],[30,155,130],[85,190,140],[180,210,120],[230,195,80],[225,145,70],[210,95,75],[175,60,80],[120,35,70],[55,18,55],[5,12,42]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const absR=Math.abs(reaction),edge=absR>0.65?1+(absR-0.65)*0.5:1;
  const angS=Math.sin(ang*2+t*0.3)*6;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+angS)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge-angS*0.5)|0)
  ];
}
